function openPage(file) {
  var status = document.getElementById("status");
  if (status) status.textContent = "c(Îý…\Ï }&";
  fetch(file, { cache: "reload" }).then(function (res) {
    if (!res.ok) throw new Error(String(res.status));
    return res.text();
  }).then(function (html) {
    var blob = new Blob([html], { type: "text/html;charset=utf-8" });
    location.assign(URL.createObjectURL(blob));
  }).catch(function () {
    if (status) status.textContent = " }1%÷(ûßOÈhÍÕ";
  });
}
document.getElementById("openLive").addEventListener("click", function () { openPage("live.html"); });
document.getElementById("openTemplate").addEventListener("click", function () { openPage("template.html"); });
